<script>
  import {onMount} from 'svelte';
  import VttIcon from './VttIcon.svelte';
  let {assets=[],scenes=[],folders=[],autoSearch=false,onclose,onimport,onplace,onupdate,onreorder,ondelete,onaddfolder,onfoldermenu,onsceneopen,onscenerename,onscenedelete}=$props();
  let category=$state('ALL'),collection=$state(''),tag=$state(''),query=$state(''),selected=$state(''),menu=$state(null),moveTarget=$state(null),assetDrop=$state(null),editingAsset=$state(''),renameValue=$state(''),fileInput,searchInput;
  const categories=[['ALL','Tous','layers'],['SCENE','Scènes','map'],['MAP','Cartes','map'],['PROP','Accessoires','prop'],['MOUNT','Montures','mount'],['CHARACTER','Personnages','character'],['NOTE','Notes','note']];
  let tags=$derived([...new Set(assets.flatMap(asset=>asset.tags||[]))].sort());
  let visible=$derived((category==='SCENE'?scenes.map(scene=>({...scene,type:'SCENE',preview:scene.thumbnail})):assets).filter(asset=>(category==='ALL'||asset.type===category)&&(!collection||asset.folderId===collection)&&(!tag||(tag==='favorite'?asset.favorite:asset.tags?.includes(tag)))&&(!query||asset.name.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>(a.order??0)-(b.order??0)));
  function startRename(asset){editingAsset=asset.id;renameValue=asset.name;menu=null;}
  function finishRename(asset){const name=renameValue.trim();if(name&&name!==asset.name)(asset.type==='SCENE'?onscenerename(asset,name):onupdate(asset.id,{name}));editingAsset='';}
  function editTags(asset){const value=prompt('Tags séparés par des virgules',(asset.tags||[]).join(', '));if(value!==null)onupdate(asset.id,{tags:[...new Set(value.split(',').map(v=>v.trim()).filter(Boolean))]});menu=null;}
  function move(asset){moveTarget=asset;menu=null;}
  function chooseMove(type){if(type!==moveTarget?.type)onupdate(moveTarget.id,{type});moveTarget=null;}
  function moveFolder(asset){const names=folders.map(folder=>folder.name).join(', '),value=prompt(`Ranger dans un dossier (${names||'aucun dossier'})`,'');if(value===null)return;const folder=folders.find(item=>item.name.toLowerCase()===value.trim().toLowerCase());onupdate(asset.id,{folderId:folder?.id||''});menu=null;}
  onMount(()=>{const close=event=>{if(event.key==='Escape')onclose()};window.addEventListener('keydown',close);if(autoSearch)setTimeout(()=>searchInput?.focus());return()=>window.removeEventListener('keydown',close)});
</script>

<div class="asset-manager-backdrop" role="presentation" onclick={onclose}>
  <section class="asset-manager" role="dialog" aria-modal="true" aria-label="Gestionnaire d’assets" onclick={e=>{e.stopPropagation();menu=null}}>
    <aside class="asset-sidebar"><header><strong>Collections</strong><button onclick={onaddfolder} title="Nouveau dossier"><VttIcon name="add" size={16}/></button></header><button class:active={!collection} onclick={()=>collection=''}><VttIcon name="layers" size={16}/>Tous les assets</button>{#each folders as folder}<button class:active={collection===folder.id} onclick={()=>collection=folder.id} ondblclick={()=>onfoldermenu(folder,'rename')} oncontextmenu={e=>{e.preventDefault();onfoldermenu(folder,'menu')}} title="Double-clic : renommer · Clic droit : options"><span>▰</span>{folder.name}</button>{/each}<header><strong>Tags</strong></header><button class:active={tag==='favorite'} onclick={()=>tag=tag==='favorite'?'':'favorite'}>♥ Favoris</button>{#each tags as value}<button class:active={tag===value} onclick={()=>tag=tag===value?'':value}># {value}</button>{/each}</aside>
    <div class="asset-main"><header><h2>Assets</h2><div class="asset-search"><VttIcon name="search" size={17}/><input bind:this={searchInput} bind:value={query} placeholder="Rechercher"></div><button class="asset-add-main" onclick={()=>fileInput.click()} title="Ajouter" aria-label="Ajouter"><VttIcon name="add" size={19}/></button><button onclick={onclose} aria-label="Fermer">×</button></header>
      <nav class="asset-categories">{#each categories as [key,label,icon]}<button class:active={category===key} onclick={()=>category=key}><VttIcon name={icon} size={16}/>{label}</button>{/each}</nav>
      <div class="asset-grid">{#each visible as asset}<button class="asset-tile" class:selected={selected===asset.id} class:drop-before={assetDrop?.id===asset.id&&!assetDrop.after} class:drop-after={assetDrop?.id===asset.id&&assetDrop.after} draggable={editingAsset!==asset.id} ondragstart={e=>{e.dataTransfer.setData(asset.type==='SCENE'?'text/vtt-scene':'text/vtt-library-asset',asset.id);e.dataTransfer.effectAllowed=asset.type==='SCENE'?'copy':'copyMove'}} ondragend={()=>assetDrop=null} ondragover={e=>{if(asset.type==='SCENE')return;e.preventDefault();const rect=e.currentTarget.getBoundingClientRect();assetDrop={id:asset.id,after:e.clientX>rect.left+rect.width/2}}} ondrop={e=>{const source=e.dataTransfer.getData('text/vtt-library-asset');if(source&&source!==asset.id){e.preventDefault();e.stopPropagation();onreorder(source,asset.id,assetDrop?.after)}assetDrop=null}} onclick={()=>selected=asset.id} ondblclick={()=>asset.type==='SCENE'?onsceneopen(asset.id):onplace(asset)} oncontextmenu={e=>{e.preventDefault();e.stopPropagation();selected=asset.id;menu={asset,x:e.clientX,y:e.clientY}}}><div>{#if asset.preview}<img src={asset.preview} alt="">{:else}<VttIcon name={asset.type?.toLowerCase()||'prop'} size={34}/>{/if}<span class="asset-folder-mark">▰</span></div>{#if editingAsset===asset.id}<input class="asset-inline-name" bind:value={renameValue} onclick={e=>e.stopPropagation()} ondblclick={e=>e.stopPropagation()} onkeydown={e=>{if(e.key==='Enter')finishRename(asset);if(e.key==='Escape')editingAsset=''}} onblur={()=>finishRename(asset)} autofocus>{:else}<span>{asset.name}</span>{/if}<i onclick={e=>{e.stopPropagation();startRename(asset)}}>✎</i></button>{:else}<p class="asset-empty">Aucun asset dans cette vue.</p>{/each}</div>
      <input bind:this={fileInput} hidden type="file" accept="image/*" multiple onchange={e=>{onimport([...e.currentTarget.files],category==='ALL'?'PROP':category);e.currentTarget.value=''}}>
    </div>
  </section>
</div>
{#if menu}<div class="asset-context" style={`left:${menu.x}px;top:${menu.y}px`} onclick={e=>e.stopPropagation()}>{#if menu.asset.type==='SCENE'}<button onclick={()=>startRename(menu.asset)}>✎ Renommer</button><button onclick={()=>{onscenedelete(menu.asset);menu=null}}>▰ Supprimer</button>{:else}<button onclick={()=>startRename(menu.asset)}>✎ Renommer</button><button onclick={()=>{onupdate(menu.asset.id,{favorite:!menu.asset.favorite});menu=null}}>♥ {menu.asset.favorite?'Retirer des favoris':'Ajouter aux favoris'}</button><button onclick={()=>editTags(menu.asset)}>◆ Tags</button><button onclick={()=>move(menu.asset)}>▰ Déplacer vers</button><button onclick={()=>moveFolder(menu.asset)}>▰ Ranger dans un dossier</button><button onclick={()=>{if(confirm('Supprimer cet asset de la bibliothèque ?'))ondelete(menu.asset.id);menu=null}}>▰ Supprimer</button>{/if}</div>{/if}
{#if moveTarget}<div class="asset-move-backdrop" role="presentation" onclick={()=>moveTarget=null}><section class="asset-move-panel" role="dialog" aria-modal="true" aria-label="Déplacer vers" onclick={e=>e.stopPropagation()}><header><strong>Déplacer vers</strong><button onclick={()=>moveTarget=null} aria-label="Fermer">×</button></header>{#each categories.filter(([key])=>!['ALL','SCENE'].includes(key)) as [key,label,icon]}<button class:active={moveTarget.type===key} onclick={()=>chooseMove(key)}><VttIcon name={icon} size={19}/><span>{label}</span>{#if moveTarget.type===key}<VttIcon name="check" size={16}/>{/if}</button>{/each}</section></div>{/if}
<style>.asset-categories{grid-template-columns:repeat(7,1fr)!important}@media(max-width:760px){.asset-categories{grid-template-columns:repeat(3,1fr)!important}}</style>
